if (open_list.empty()) return nullptr;

auto min_it = std::min_element(open_list.begin(), open_list.end(),
    [](Node* a, Node* b) {
        return (a->g + a->h) < (b->g + b->h);
    });

Node* best = *min_it;
open_list.erase(min_it);
return best;
